// conf/transform/voltage_to_soc.js (or voltage_to_soc_fine.js)
(function(input) {
    // --- Input Validation ---
    if (input === null || input === undefined || typeof input !== 'string' || input == 'NULL' || input == 'UNDEF') {
        return "N/A"; // Return N/A for the transformation part
    }

    // Handle potential units (e.g., "50.5 V")
    var v = parseFloat(input.split(' ')[0]);

    if (isNaN(v)) {
        return "N/A"; // Return N/A if parsing failed
    }

    // --- Voltage-SoC Mapping Points ---
    // Define the known points based on your original logic.
    // IMPORTANT: Must be sorted by Voltage in ASCENDING order.
    const points = [
        // [Voltage, SoC]
        // Add a lower bound if needed, e.g., [44.0, 0] if 44.0V truly means 0%
        // Using your lowest threshold as the first point for interpolation:
        [44.4, 10],
        [45.2, 20],
        [46.0, 30],
        [46.8, 40],
        [47.6, 50],
        [48.4, 60],
        [49.2, 70],
        [50.0, 80],
        [50.8, 90],
        [52.0, 100]
    ];

    // --- Handle Edge Cases ---
    // Voltage below the lowest defined point (use 0% like your original logic)
    if (v < points[0][0]) { // Voltage is lower than 44.4V
        return 0;
    }
    // Voltage at or above the highest defined point
    if (v >= points[points.length - 1][0]) { // Voltage is 52.0V or higher
        return points[points.length - 1][1]; // Return 100%
    }

    // --- Linear Interpolation ---
    // Find the two points the current voltage 'v' falls between
    for (let i = 0; i < points.length - 1; i++) {
        const p1 = points[i];     // Lower point [v1, soc1]
        const p2 = points[i+1];   // Upper point [v2, soc2]

        // Check if voltage 'v' is within the segment [v1, v2)
        if (v >= p1[0] && v < p2[0]) {
            const v1 = p1[0];
            const soc1 = p1[1];
            const v2 = p2[0];
            const soc2 = p2[1];

            // Calculate the proportion of how far 'v' is between v1 and v2
            const proportion = (v - v1) / (v2 - v1);

            // Apply that proportion to the SoC range [soc1, soc2]
            const interpolatedSoc = soc1 + proportion * (soc2 - soc1);

            // Round to the nearest whole number for display
            return Math.round(interpolatedSoc);
        }
    }

    // --- Fallback ---
    // This part should ideally not be reached if the points cover the range
    // and edge cases are handled correctly.
    // Could return the closest known point or N/A.
    // Let's return N/A for safety.
    return "N/A";

})(input) // Special variable 'input' holds the item state passed to the transform
